            "badgeColor": "emerald",
            "visualSvg": "\n          <svg width=\"680\" height=\"480\" viewBox=\"-15 -15 710 510\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style=\"overflow: visible;\">\n            <rect x=\"60\" y=\"50\" width=\"560\" height=\"380\" rx=\"20\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#10b981\" stroke-width=\"2.5\"/>\n            <text x=\"340\" y=\"98\" text-anchor=\"middle\" fill=\"#10b981\" font-size=\"20\" font-weight=\"bold\">چرخه بازاریابی سیستماتیک و پایدار</text>\n            <line x1=\"90\" y1=\"125\" x2=\"590\" y2=\"125\" stroke=\"rgba(255,255,255,0.1)\" stroke-width=\"1.5\"/>\n\n            <rect x=\"90\" y=\"145\" width=\"500\" height=\"48\" rx=\"12\" fill=\"rgba(56,189,248,0.12)\" stroke=\"rgba(56,189,248,0.3)\" stroke-width=\"1.5\"/>\n            <text x=\"340\" y=\"175\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"14\">۱. تولید محتوای تخصصی و رتبه‌گیری مستمر در سئو</text>\n\n            <rect x=\"90\" y=\"208\" width=\"500\" height=\"48\" rx=\"12\" fill=\"rgba(52,211,153,0.12)\" stroke=\"rgba(52,211,153,0.3)\" stroke-width=\"1.5\"/>\n            <text x=\"340\" y=\"238\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"14\">۲. جمع‌آوری ایمیل لیدها با کتابچه راهنما یا ابزار رایگان</text>\n\n            <rect x=\"90\" y=\"271\" width=\"500\" height=\"48\" rx=\"12\" fill=\"rgba(251,191,36,0.12)\" stroke=\"rgba(251,191,36,0.3)\" stroke-width=\"1.5\"/>\n            <text x=\"340\" y=\"301\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"14\">۳. دنباله‌سازی ایمیلی خودکار و ایجاد اعتماد (Autoresponder)</text>\n\n            <rect x=\"90\" y=\"334\" width=\"500\" height=\"52\" rx=\"12\" fill=\"rgba(16,185,129,0.2)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n            <text x=\"340\" y=\"366\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"14.5\" font-weight=\"bold\">۴. فروش مستقیم نرم‌افزار بدون نیاز به تماس تلفنی</text>\n          </svg>\n        ",
