            "badgeColor": "cyan",
            "visualSvg": "\n      <svg width=\"680\" height=\"480\" viewBox=\"-15 -15 710 510\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style=\"overflow: visible;\">\n        <rect x=\"80\" y=\"110\" width=\"230\" height=\"260\" rx=\"16\" fill=\"rgba(15,23,42,0.85)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n        <text x=\"195\" y=\"160\" text-anchor=\"middle\" fill=\"#ef4444\" font-size=\"18\" font-weight=\"bold\">زمان شما به عنوان برنامه‌نویس</text>\n        <text x=\"195\" y=\"210\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"22\" font-weight=\"bold\">۵۰ تا ۱۰۰ دلار / ساعت</text>\n        <text x=\"195\" y=\"260\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"12\">اگر کارهای ادمینی، ورود داده و</text>\n        <text x=\"195\" y=\"285\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"12\">سرچ دستی را خودتان انجام دهید:</text>\n        <text x=\"195\" y=\"325\" text-anchor=\"middle\" fill=\"#ef4444\" font-size=\"14\" font-weight=\"bold\">سوزاندن سرمایه اصلی استارتاپ!</text>\n\n        <rect x=\"370\" y=\"110\" width=\"230\" height=\"260\" rx=\"16\" fill=\"rgba(15,23,42,0.85)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n        <text x=\"485\" y=\"160\" text-anchor=\"middle\" fill=\"#10b981\" font-size=\"18\" font-weight=\"bold\">هزینه دستیار مجازی (VA)</text>\n        <text x=\"485\" y=\"210\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"22\" font-weight=\"bold\">۵ تا ۱۰ دلار / ساعت</text>\n        <text x=\"485\" y=\"260\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"12\">انجام تسک‌های تکراری، لیست‌ها</text>\n        <text x=\"485\" y=\"285\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"12\">پاسخ به سوالات اولیه کاربران</text>\n        <text x=\"485\" y=\"325\" text-anchor=\"middle\" fill=\"#10b981\" font-size=\"14\" font-weight=\"bold\">۱۰ برابر صرفه‌جویی در انرژی!</text>\n      </svg>\n    ",
